class Carrinho:
    def __init__(self, cliente):
        self.cliente = cliente
        self.__itens = []

    def adicionar(self, produto, quantidade=1):
        if quantidade > produto.estoque:
            print(f"Não há {quantidade} unidade(s) de {produto.nome} em estoque.")
            return
        self.__itens.append(ItemCarrinho(produto, quantidade))

    @property
    def total(self):
        return sum(item.subtotal for item in self.__itens)

    def finalizar(self):
        for item in self.__itens:
            item.produto.baixar_estoque(item.quantidade)
        print(f"Pedido de {self.cliente.nome} confirmado: R$ {self.total:.2f}")
        for item in self.__itens:
            print(f"  {item.quantidade}x {item.produto.nome} = R$ {item.subtotal:.2f}")
        self.__itens = []


