class Conta:
    def __init__(self, titular, saldo=0):
        self.titular = titular
        self.__saldo = saldo
        self.__extrato = []

    @property
    def saldo(self):
        return self.__saldo

    @property
    def extrato(self):
        return list(self.__extrato)

    def depositar(self, valor):
        if valor <= 0:
            raise ValueError("Depósito deve ser positivo.")
        self.__saldo += valor
        self.__extrato.append(f"+{valor:.2f}")

    def sacar(self, valor):
        if valor > self.__saldo:
            raise ValueError("Saldo insuficiente.")
        self.__saldo -= valor
        self.__extrato.append(f"-{valor:.2f}")

